name: Claude PR Critique
on:
  pull_request:
    types: [opened, synchronize, reopened]

jobs:
  claude-critique:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout code
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Run Claude PR Critique
        id: claude-critique
        uses: anthropics/claude-code-base-action@beta
        with:
          prompt: "Provide a brief critique of this pull request. Focus on code quality, potential bugs, and maintainability. Keep it concise and actionable. Format your response as markdown."
          allowed_tools: "Bash(git diff --name-only HEAD~1),Bash(git diff HEAD~1),View,GlobTool,GrepTool,Write"
          anthropic_api_key: ${{ secrets.ANTHROPIC_API_KEY }}

      - name: Extract and Comment PR Review
        if: steps.claude-critique.outputs.conclusion == 'success'
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const fs = require('fs');
            const executionFile = '${{ steps.claude-critique.outputs.execution_file }}';
            const executionLog = JSON.parse(fs.readFileSync(executionFile, 'utf8'));

            // Extract the critique content from the execution log
            let critique = '';

            // Find the last assistant message which should contain the critique
            for (let i = executionLog.length - 1; i >= 0; i--) {
              if (executionLog[i].role === 'assistant') {
                critique = executionLog[i].content;
                break;
              }
            }

            if (critique) {
              github.rest.issues.createComment({
                issue_number: context.issue.number,
                owner: context.repo.owner,
                repo: context.repo.repo,
                body: "## Claude PR Critique\n\n" + critique + "\n\n*Generated by Claude Code*"
              });
            }
